    row_colors = [row[0] for row in grid]
    counts = {c: row_colors.count(c) for c in set(row_colors)}

    repeated = [c for c, n in counts.items() if n > 1]
    marker = max(repeated, key=lambda c: counts[c])
    positions = [i for i, c in enumerate(row_colors) if c == marker]
    period = positions[1] - positions[0]
    phase = positions[0] % period

    background = max(counts, key=counts.get)
    if background == marker:
        background = 0

    return [
        [marker if r % period == phase else background for _ in range(w)]
        for r in range(h)
    ]
