def transform(grid):
    h, w = len(grid), len(grid[0])
    rows = [row[0] for row in grid]

    # Uniform-row encoding: discard blank padding and tile the remaining
    # color sequence, using the first nonblank row as the phase anchor.
    if all(all(v == row[0] for v in row) for row in grid):
        seq = [c for c in rows if c != 0]
        if not seq:
            return [row[:] for row in grid]
        start = next(i for i, c in enumerate(rows) if c != 0)
        return [[seq[(r - start) % len(seq)]] * w for r in range(h)]

    # For the diagonal encoding, the grid describes a cyclic diagonal
    # color pattern; extend it as a doubly-periodic pattern.
    n = len(grid)
    pattern = {}
    for r in range(n):
        for c in range(n):
            v = grid[r][c]
            if v != 0:
                pattern[(c - r) % n] = v
    keys = sorted(pattern)
    if not keys:
        return [row[:] for row in grid]
    for k in range(n):
        if k not in pattern:
            pattern[k] = pattern[keys[0]]
    return [[pattern[(c - r) % n] for c in range(w)] for r in range(h)]
